mapper.select:
select count(bp.origin_type)
from base_patient bp

    bp.origin_type_name is not null
    and bp.origin_type is not null

        AND bp.org_id = #{form.orgId}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) =#{form.year}

select
bp.origin_type originType,
bp.origin_type_name originTypeName,
count(bp.origin_type) countType,
concat( format(count(bp.origin_type) / ${countOriginType} * 100, 2 ),'%') percentage
from base_patient bp

    bp.origin_type_name is not null
    and bp.origin_type is not null

        AND bp.org_id = #{form.orgId}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) = #{form.year}


group by bp.origin_type

select count(bp.gender)
from base_patient bp

    bp.gender is not null

        AND bp.org_id = #{form.orgId}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) =#{form.year}

select
case when bp.gender = 0 then '男'
when bp.gender = 1 then '女'
end gender,
count(bp.gender) countGender,
concat( format(count(bp.gender) / ${countGender} * 100, 2 ),'%') percentage
from base_patient bp

    bp.gender is not null

        AND bp.org_id = #{form.orgId}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) =#{form.year}


group by bp.gender

select count(1) from base_patient bp

    bp.birthday is not null

        AND bp.org_id = #{form.orgId}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) =#{form.year}

select count(1) from base_patient bp

    bp.birthday is not null

        AND bp.org_id = #{form.orgId}



        AND ( DATE_FORMAT(now(),'%Y-%m-%d') - DATE_FORMAT(bp.birthday,'%Y-%m-%d') ) <= #{ageOne}



        AND ( DATE_FORMAT(now(),'%Y-%m-%d') - DATE_FORMAT(bp.birthday,'%Y-%m-%d') ) >= #{ageTwo}



        AND ( DATE_FORMAT(now(),'%Y-%m') - DATE_FORMAT(bp.birthday,'%Y-%m') ) <= #{ageThree}



        AND cast(bp.patient_crt_time as date) between #{form.startDate} and #{form.endDate}



        AND DATE_FORMAT(bp.patient_crt_time,'%Y-%m') = #{form.monthDay}



        AND year(bp.patient_crt_time) =#{form.year}

select treatmentId, patientId, name, mobile, treatType, dentistId, employeeName, lastVisitDate from ( SELECT btp.orgId, btp.treatmentId, btp.patientId, btp.treatType, btp.dentistId, btp.employeeName, btp.lastVisitDate, bp.`name` as `name`, bp.mobile as mobile, bp.pinyin_name AS pinyinName, IFNULL( btp1.appointCount, 0 ) AS appointCount, IFNULL( bvr.visitCount, 0 ) AS visitCount FROM ( SELECT btp1.org_id AS orgId, btp1.treatment_id AS treatmentId, btp1.patient_id AS patientId, btp1.treat_type AS treatType, btp1.registered_dentist_id AS dentistId, btp1.employee_name AS employeeName, DATE_FORMAT( btp1.treat_start_time, '%Y-%m-%d' ) AS lastVisitDate FROM ( SELECT max( btp.treatment_id ) AS treatmentId FROM base_treatment_process btp WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.patient_id ) btp LEFT JOIN ( SELECT any_value ( btp.org_id ) AS org_id, any_value ( btp.treatment_id ) AS treatment_id, any_value ( btp.patient_id ) AS patient_id, any_value ( btp.registered_dentist_id ) AS registered_dentist_id, any_value ( btp.treat_start_time ) AS treat_start_time, any_value ( btp.treat_type ) AS treat_type, any_value ( be.employee_name ) AS employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.treatment_id ) btp1 ON btp.treatmentId = btp1.treatment_id ) btp LEFT JOIN base_patient bp ON btp.patientId = bp.patient_id LEFT JOIN ( SELECT patient_id, count( btp.patient_id ) AS appointCount FROM base_treatment_process btp WHERE btp.appointment_id IS NOT NULL AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) > DATE_FORMAT( CURRENT_DATE, '%Y-%m-%d' ) GROUP BY patient_id ) btp1 ON btp.patientId = btp1.patient_id LEFT JOIN ( SELECT patient_id, count( bvr.patient_id ) AS visitCount FROM base_visit_remind bvr WHERE bvr.type = 0 AND DATE_FORMAT( bvr.time, '%Y-%m-%d' ) > DATE_FORMAT( CURRENT_DATE, '%Y-%m-%d' ) GROUP BY patient_id ) bvr ON btp.patientId = bvr.patient_id ) btp
and btp.appointCount = 0 and btp.visitCount = 0
and btp.orgId = #{form.orgId}
and btp.lastVisitDate >= #{form.startDate}
and btp.lastVisitDate <= #{form.endDate}
and btp.dentistId in
#{item}
and concat(IFNULL(btp.`name`,''),IFNULL(btp.pinyinName,''),IFNULL(btp.mobile,'')) like concat(concat('%',#{form.combination}),'%')
and btp.treatType in
#{item}
